from dataclasses import dataclass, field


@dataclass(frozen=True)
class Config:
    host: str
    port: int = 8080


@dataclass(order=True)
class Priority:
    level: int
    name: str


@dataclass
class Tasks:
    title: str
    items: list = field(default_factory=list)

    def add(self, item):
        self.items.append(item)
